def applications(served: Served) -> Dict[str, ASGIApp]:
  """Each service's application, by the path its calls start with."""
  return {
    "/pylabrobot.brooks.precise_flex.server.v1.PreciseFlexService/": precise_flex_connect.PreciseFlexServiceASGIApplication(PreciseFlexHandlers(served)),
    "/pylabrobot.brooks.precise_flex.server.v1.DriverService/": driver_connect.DriverServiceASGIApplication(DriverHandlers(served)),
    "/pylabrobot.brooks.precise_flex.server.v1.ArmService/": arm_connect.ArmServiceASGIApplication(ArmHandlers(served)),
    "/pylabrobot.brooks.precise_flex.server.v1.GripperService/": gripper_connect.GripperServiceASGIApplication(GripperHandlers(served)),
    "/pylabrobot.brooks.precise_flex.server.v1.RailService/": rail_connect.RailServiceASGIApplication(RailHandlers(served)),
    "/pylabrobot.brooks.precise_flex.server.v1.VisionService/": vision_connect.VisionServiceASGIApplication(VisionHandlers(served)),
  }
